import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {getOverviewHref} from '../../../../routes'
import {
  getBuild,
  getBuildStatusType,
  getIsSakuraUI,
  getPipelineBatchIdFromBuildId,
  getPipelineIdFromBuildId,
  getPipelineJobIdFromBuildId,
  getPipelineRunIdFromBuildId,
} from '../../../../selectors'
import {resolveWebEntityLink, WebEntityType} from '../../../../utils/entityLinks'

import BuildStatusLink from './BuildStatusLink'
import type {OwnProps, StateProps} from './BuildStatusLink.types'

const mapStateToProps = (state: State, {buildId}: OwnProps): StateProps => {
  const isSakuraUI = getIsSakuraUI(state)
  const build = getBuild(state, buildId)
  const {statusText, waitReason, startEstimate, number, queuePosition} = build || {}
  const pipelineId = getPipelineIdFromBuildId(state, buildId)
  const runId = getPipelineRunIdFromBuildId(state, buildId)
  const jobId = getPipelineJobIdFromBuildId(state, buildId)
  const batchId = getPipelineBatchIdFromBuildId(state, buildId)
  const link = isSakuraUI
    ? getOverviewHref({
        buildId,
        buildTypeId: build?.buildType,
        pipelineId,
        runId,
      }).concat(
        jobId ? `?${objectToQuery({job: jobId ?? null, pageFullLogBuildId: batchId ?? null})}` : '',
      )
    : resolveWebEntityLink(WebEntityType.BUILD, buildId)
  return {
    statusType: getBuildStatusType(state, buildId),
    isSakuraUI: getIsSakuraUI(state),
    buildUrl: link || '',
    statusText,
    number,
    isQueued: build?.state === 'queued',
    queuePosition,
    waitReason,
    startEstimate,
  }
}

export default connect(mapStateToProps)(BuildStatusLink)
