import {connect} from 'react-redux'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {State} from '../../../../../reducers/types'
import {getBuild} from '../../../../../selectors'
import type {BuildId, BuildTypeId} from '../../../../../types'

import type {BuildPersonalChangeCommentQuery} from './BuildPersonalChangeComment/__generated__/BuildPersonalChangeCommentQuery.graphql'
import BuildStatusTooltip from './BuildStatusTooltip'

type OwnProps = {
  personalChangeCommentQueryRef?: PreloadedQuery<BuildPersonalChangeCommentQuery> | null
  buildId: BuildId
}
type StateProps = {
  buildTypeId?: BuildTypeId | null | undefined
}

const mapStateToProps = (state: State, {buildId}: OwnProps): StateProps => {
  const {buildType} = getBuild(state, buildId) || {}
  return {
    buildTypeId: buildType,
  }
}

export default connect(mapStateToProps)(BuildStatusTooltip)
